USE campushire;
CREATE OR REPLACE VIEW student_application_summary AS SELECT s.student_id,s.registration_no,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) student_name,COUNT(a.application_id) total_applications,SUM(a.status IN('under_review','shortlisted','interview','offered')) active_applications,SUM(a.status='shortlisted') shortlisted_applications,SUM(a.status='offered') offered_applications,SUM(a.status='rejected') rejected_applications FROM students s LEFT JOIN applications a ON a.student_id=s.student_id GROUP BY s.student_id,s.registration_no,s.first_name,s.last_name;
CREATE OR REPLACE VIEW internship_application_stats AS SELECT i.internship_id,i.title,i.company_id,i.openings,COUNT(a.application_id) applications,SUM(a.status='shortlisted') shortlisted,SUM(a.status='interview') interviewing,SUM(a.status='offered') offered FROM internships i LEFT JOIN applications a ON a.internship_id=i.internship_id GROUP BY i.internship_id,i.title,i.company_id,i.openings;
CREATE OR REPLACE VIEW company_recruitment_summary AS SELECT c.company_id,c.name,COUNT(DISTINCT i.internship_id) internships,COUNT(DISTINCT a.application_id) applications,COUNT(DISTINCT o.offer_id) offers,COUNT(DISTINCT CASE WHEN o.status='accepted' THEN o.offer_id END) accepted_offers FROM companies c LEFT JOIN internships i ON i.company_id=c.company_id LEFT JOIN applications a ON a.internship_id=i.internship_id LEFT JOIN offers o ON o.application_id=a.application_id GROUP BY c.company_id,c.name;
CREATE OR REPLACE VIEW placement_statistics AS SELECT d.department_id,d.code,d.name,COUNT(DISTINCT s.student_id) students,COUNT(DISTINCT a.application_id) applications,COUNT(DISTINCT o.offer_id) offers,COUNT(DISTINCT CASE WHEN o.status='accepted' THEN o.offer_id END) accepted_offers FROM departments d LEFT JOIN students s ON s.department_id=d.department_id LEFT JOIN applications a ON a.student_id=s.student_id LEFT JOIN offers o ON o.application_id=a.application_id GROUP BY d.department_id,d.code,d.name;
CREATE OR REPLACE VIEW application_funnel_statistics AS SELECT COUNT(*) applications,SUM(status IN('under_review','shortlisted','interview','offered')) reviewed_or_beyond,SUM(status IN('shortlisted','interview','offered')) shortlisted_or_beyond,SUM(status IN('interview','offered')) interviewed_or_beyond,SUM(status='offered') offered,SUM(status='rejected') rejected,SUM(status='withdrawn') withdrawn FROM applications;
CREATE OR REPLACE VIEW skill_demand_statistics AS SELECT s.skill_id,s.name,s.category,COUNT(x.internship_id) internships_requiring_skill FROM skills s LEFT JOIN internship_skills x ON x.skill_id=s.skill_id GROUP BY s.skill_id,s.name,s.category;
CREATE OR REPLACE VIEW internship_outcome_statistics AS SELECT i.internship_id,i.title,c.name company,COUNT(DISTINCT a.application_id) applications,COUNT(DISTINCT iv.interview_id) interviews,COUNT(DISTINCT o.offer_id) offers,COUNT(DISTINCT CASE WHEN o.status='accepted' THEN o.offer_id END) accepted_offers,COUNT(DISTINCT CASE WHEN r.status='completed' THEN r.record_id END) completed,ROUND(AVG(e.score),2) avg_evaluation FROM internships i JOIN companies c ON c.company_id=i.company_id LEFT JOIN applications a ON a.internship_id=i.internship_id LEFT JOIN interviews iv ON iv.application_id=a.application_id LEFT JOIN offers o ON o.application_id=a.application_id LEFT JOIN internship_records r ON r.offer_id=o.offer_id LEFT JOIN evaluations e ON e.record_id=r.record_id GROUP BY i.internship_id,i.title,c.name;
